package com.shengxu.controller;
import com.shengxu.dto.*; import com.shengxu.dto.AuthDtos.UserView; import com.shengxu.service.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.Map;
@RestController @RequestMapping("/api/v1/users/me")
public class UserController {private final AuthService auth;private final UserService users;public UserController(AuthService a,UserService u){auth=a;users=u;}@GetMapping public ApiResponse<UserView> me(Authentication a){return ApiResponse.ok(auth.me((Long)a.getPrincipal()));}@PatchMapping public ApiResponse<UserView> update(Authentication a,@RequestBody Map<String,String> body){users.update((Long)a.getPrincipal(),body.get("username"));return ApiResponse.ok(auth.me((Long)a.getPrincipal()));}@PostMapping("/avatar") public ApiResponse<Map<String,String>> avatar(Authentication a,@RequestParam("file") MultipartFile f){return ApiResponse.ok(Map.of("avatarUrl",users.avatar((Long)a.getPrincipal(),f)));}}

